import * as s from "../core/validation/index.js";
import type { Schema } from "../core/validation/schema.js";
import { segmentSchema, type Segment } from "./segment.js";

export type Chunk = {
  /** The unique identifier for the chunk. */
  chunkId?: string;
  /** The total number of tokens in the chunk. Calculated by the `tokenizer`. */
  chunkLength: number;
  /**
   * Suggested text to be embedded for the chunk. This text is generated by combining the embed
   * content from each segment according to the configured embed sources (HTML, Markdown, LLM, or
   * Content). Can be configured using `embed_sources` in the `SegmentProcessing` configuration.
   */
  embed?: string | null;
  /**
   * Collection of document segments that form this chunk. When `target_chunk_length` > 0, contains
   * the maximum number of segments that fit within that length (segments remain intact). Otherwise,
   * contains exactly one segment.
   */
  segments: Segment[];
};

export const chunkSchema: Schema<Chunk> = s.object<Chunk>({
  chunkId: s.optional(s.string()),
  chunkLength: s.number(),
  embed: s.optionalNullable(s.string()),
  segments: s.array(s.lazy(() => segmentSchema)),
  _keysMap: {
    chunkId: "chunk_id",
    chunkLength: "chunk_length",
  },
});
